import re,os,json,html
os.chdir(os.path.expanduser('~/mnt/dental-concept'))
MISS=[]
def R(s,old,new,label=''):
    if old in s: return s.replace(old,new,1)
    if new in s: return s
    MISS.append(label or old[:70]);return s
def RX(s,pat,new,label):
    s2,n=re.subn(pat,lambda m:new,s,count=1,flags=re.S)
    if n==0 and new not in s: MISS.append(label)
    return s2
def meta(s,title,desc):
    T=html.escape(title,quote=True);M=html.escape(desc,quote=True)
    s=re.sub(r'<title>.*?</title>','<title>'+T+'</title>',s,count=1)
    for a in ['name="description"','property="og:description"','name="twitter:description"']: s=re.sub(r'(<meta '+a+r' content=")[^"]*',lambda m:m.group(1)+M,s,count=1)
    for a in ['property="og:title"','name="twitter:title"']: s=re.sub(r'(<meta '+a+r' content=")[^"]*',lambda m:m.group(1)+T,s,count=1)
    j=lambda t:json.dumps(t,ensure_ascii=False)[1:-1]
    s=re.sub(r'("@type":"WebPage","name":)"[^"]*","description":"[^"]*"',lambda m:m.group(1)+'"'+j(title)+'","description":"'+j(desc)+'"',s,count=1)
    return s
def faqlist(s,qa,label):
    body=''.join('<details><summary>%s</summary><div class="faq-answer"><p>%s</p></div></details>'%(q,a) for q,a in qa)
    s=RX(s,r'<div class="faq-list">.*?</div></div></section>','<div class="faq-list">'+body+'</div></div></section>',label)
    fj={"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":html.unescape(re.sub('<[^>]+>','',q)),"acceptedAnswer":{"@type":"Answer","text":html.unescape(re.sub('<[^>]+>','',a))}} for q,a in qa]}
    s=re.sub(r'<script type="application/ld\+json" id="faq-ld">.*?</script>','',s,flags=re.S)
    return s.replace('</head>','<script type="application/ld+json" id="faq-ld">'+json.dumps(fj,ensure_ascii=False)+'</script></head>',1)
